from autograd import Tensor
from seq_ops_l4 import block, init_block

_g = np.random.default_rng(8)
P4 = init_block(4, 8, seed=2)
for _k in P4:
    P4[_k] = P4[_k] + 0.1 * _g.standard_normal(P4[_k].shape)
X3 = _g.standard_normal((3, 4))
M3 = _g.standard_normal((3, 4))


def good(x, P):
    return block(x, P, 2)


def no_bo_grad(x, P):
    # a planted bug: the attention output bias is used as a constant, so it never gets a gradient
    Q = dict(P)
    Q['bo'] = P['bo'].data
    return block(x, Q, 2)


def no_x_grad(x, P):
    # a second planted bug: the input is used as a constant, so it never gets a gradient
    return block(Tensor(x.data), P, 2)

